# Generated by manage.py generate_test_cases.
from bs4 import BeautifulSoup
from django.http import HttpResponse

from bloomerp.models.document_templates.document_template import DocumentTemplate
from bloomerp.tests.base import (
    BloomerpDetailViewTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestDocumentTemplateBuilderEditView(BloomerpDetailViewTestCase):
    """Tests class `DocumentTemplateBuilderEditView` from `bloomerp/views/document_templates/document_template_builder_view.py`."""

    view_name = 'builder'
    model = DocumentTemplate
    page_break_template = (
        '<p>Before</p><div data-document-template-page-break="true"></div><p>After</p>'
    )

    def create_test_object(self) -> DocumentTemplate:
        """Create the persisted document template edited by each request scenario."""
        return DocumentTemplate.objects.create(
            name="A name", template="<p>Original</p>"
        )

    def prepare_saved_page_break(self, scenario: RequestScenario) -> None:
        """Load the editor from an already persisted semantic page-break marker."""
        template = self.get_test_object()
        template.template = self.page_break_template
        template.save(update_fields=["template"])

    def validate_loaded_page_break(self, response: HttpResponse) -> bool:
        """Verify the hidden submission value and document-template editor context."""
        markup = BeautifulSoup(response.content, "html.parser")
        editor = markup.select_one('[data-editor-context="document-template"]')
        self.assertIsNotNone(editor)
        field = editor.select_one('input[name="template"]')
        self.assertIsNotNone(field)
        self.assertEqual(field["value"], self.page_break_template)
        return True

    def validate_saved_page_break(self, response: HttpResponse) -> bool:
        """Read the database again to prove the builder POST retains marker HTML."""
        template = DocumentTemplate.objects.get(pk=self.get_test_object().pk)
        self.assertEqual(template.template, self.page_break_template)
        self.assertEqual(template.name, "Saved page break template")
        return True
    
    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover editor loading and lossless template page-break save/reload paths."""
        self.get_test_object()
        return [
            RequestScenario(
                name="View loads normally",
                method="GET",
                user=self.admin_user,
            ),
            RequestScenario(
                name="Reload a saved marker into the document-template editor",
                method="GET",
                user=self.admin_user,
                prepare=self.prepare_saved_page_break,
                expected=ExpectedResult(response_validators=self.validate_loaded_page_break),
            ),
            RequestScenario(
                name="Save semantic page-break HTML through the builder form",
                method="POST",
                user=self.admin_user,
                data={
                    "name": "Saved page break template",
                    "template": self.page_break_template,
                    "page_orientation": "portrait",
                    "page_size": "A4",
                    "page_margin": "1.0",
                    "free_variables": "[]",
                    "custom_styling": "",
                },
                expected=ExpectedResult(
                    status_code=302,
                    response_validators=self.validate_saved_page_break,
                ),
            ),
        ]
